```js
const MIN_PORT = 1;
const MAX_PORT = 65535;

export function parsePort(value) {
  if (typeof value !== 'number' && typeof value !== 'string') {
    throw new RangeError(`Invalid port: ${String(value)}`);
  }

  const port = Number(value);

  if (!Number.isInteger(port) || port < MIN_PORT || port > MAX_PORT) {
    throw new RangeError(
      `Invalid port: ${String(value)} (expected an integer between ${MIN_PORT} and ${MAX_PORT})`,
    );
  }

  return port;
}
```

- Accepts: integer `1`–`65535`, including numeric strings (`parsePort("8080") === 8080`), preserving the original coercion intent for CLI/env input.
- Throws `RangeError`: `0`, `-1`, `65536`, `70000`, `1.5`, `NaN`, `±Infinity`, `""`, `"   "`, `"abc"`, `"80abc"`, `null`, `undefined`, booleans, objects, arrays, functions.
- One error type for all invalid inputs keeps plain `assert.throws(fn)` and negative-case type checks consistent.

